        for nox, noy in legal_opp:
            v = dist2(nsx, nsy, nox, noy)
            if v > worst:
                worst = v

        # Tie-break: prefer moves that also reduce immediate distance
        immediate = dist2(nsx, nsy, ox, oy)
        key = (worst, immediate)
        best_key = (best_val, dist2(sx + best_move[0], sy + best_move[1], ox, oy))
        if key < best_key:
            best_val = worst
            best_move = [dx, dy]

    return best_move

